import logging
import logging.handlers
import time

from ute_common_abstract_core import logger as core_logging  # type: ignore

from taf.ul.ue.sim.env_setup.settings import (
    NMAP_LOGGER,
    PACKAGE_NAME,
    RECOVERY_LOG_NAME,
)

MAIN_LOGGER_FORMAT = (
    "%(asctime)s | %(name)-45s | %(levelname)-8s | %(threadName)-10s | %(message)s /// "
    "%(funcName)s::%(filename)s(%(lineno)d)"
)


def debug_level_or_info_level():
    """return debugging level is set, else INFO level"""
    if core_logging.debug_level is not None:
        level = core_logging.debug_level
    else:
        level = logging.INFO
    return level


def configure_logger(name, call_counter):
    current_time = time.strftime("%H:%M:%S", time.localtime())
    log_file_name = f"{name}_{call_counter}.log"
    core_logging.create_logger(
        name=name,
        log_file=log_file_name.format(current_time),
        log_level=logging.DEBUG,
        log_format=MAIN_LOGGER_FORMAT,
    )
    logger = logging.getLogger(name)
    logger.propagate = False


def configure_env_setup_main_logger(call_counter):
    """Configure main logger of messaging"""
    configure_logger(PACKAGE_NAME, call_counter)


def configure_env_setup_recoveries_logger(call_counter):
    configure_logger(RECOVERY_LOG_NAME, call_counter)


def configure_env_setup_nmap_logger(call_counter):
    """Configure nmap logger of messaging"""
    configure_logger(NMAP_LOGGER, call_counter)


def configure_env_configurator_loggers(log_path, call_counter=0):
    """Configure all loggers"""
    core_logging.set_logging_path(log_path)
    core_logging.configure_debug_level()
    configure_env_setup_main_logger(call_counter)
    configure_env_setup_recoveries_logger(call_counter)
    configure_env_setup_nmap_logger(call_counter)
